const D = { energy:.6, scale:1, density:.5, speed:1, hue:26, wig:.55, rings:.6, x:.5, y:.5, style:'inlay', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, H = ((P.hue%360)+360)%360, en = cl(P.energy,0,1);
const sp = .25 + .75*P.speed;
const lift = .55 + .45*K.intensity;
const bass = (S.b = (S.b||0)*.84 + (A.bass||0)*.16);

// ---- an interlocking tile that PROVABLY tiles the plane -------------------
// Start from the regular hexagon (a parallelogon). Its neighbour across edge i
// is the translate by T_i = v_i + v_{i+1}. For the tile to keep tiling after we
// deform edge i into any curve C, edge i+3 must become exactly reverse(C - T_i).
// Every wiggle we add is mirrored onto the opposite edge, so the shape can morph
// live -- as wildly as it likes -- and the coronas still lock together with zero
// gap. Endpoints are pinned because every harmonic is sin(pi*h*f), zero at f=0,1.
const VX=[], VY=[];
for (let i=0;i<6;i++){ const a = Math.PI/6 + i*Math.PI/3; VX[i]=Math.cos(a); VY[i]=Math.sin(a); }
const TXv=[], TYv=[];
for (let i=0;i<3;i++){ TXv[i]=VX[i]+VX[(i+1)%6]; TYv[i]=VY[i]+VY[(i+1)%6]; }

const MS = 6;
const wig = cl(P.wig,0,1) * (.35 + .85*en) * .34;
const EDG = [];
for (let i=0;i<3;i++){
  const x0=VX[i], y0=VY[i], x1=VX[(i+1)%6], y1=VY[(i+1)%6];
  let tx=x1-x0, ty=y1-y0; const tl=Math.hypot(tx,ty)||1; tx/=tl; ty/=tl;
  const nx=-ty, ny=tx;
  const pts=[];
  for (let s=0;s<=MS;s++){
    const f=s/MS;
    let amp=0;
    for (let hh=1;hh<=3;hh++){
      const a0 = (fr(i*17.3+hh*5.1)*2-1)/hh;
      const ph = K.t*(.061*hh + .047*fr(i*3.1+hh)) * sp + fr(i*7.7+hh*2.3)*6.283;
      amp += a0*Math.sin(Math.PI*hh*f + 0)*Math.sin(ph)*0.9 + a0*Math.sin(Math.PI*hh*f)*.45;
    }
    amp *= wig*tl;
    let tg = 0;
    for (let hh=1;hh<=2;hh++){
      const b0 = (fr(i*23.9+hh*11.7)*2-1)/hh;
      tg += b0*Math.sin(Math.PI*hh*f)*Math.sin(K.t*(.083+.037*hh)*sp + fr(i*13.1+hh)*6.283);
    }
    tg *= wig*tl*.5;
    pts.push(x0+tx*(f*tl+tg)+nx*amp, y0+ty*(f*tl+tg)+ny*amp);
  }
  EDG[i]=pts;
}
for (let i=0;i<3;i++){                       // the forced opposite edges
  const src=EDG[i], out=[];
  for (let s=MS;s>=0;s--){ out.push(src[s*2]-TXv[i], src[s*2+1]-TYv[i]); }
  EDG[i+3]=out;
}
const BX=[], BY=[];
for (let i=0;i<6;i++){ const e=EDG[i]; for (let s=0;s<MS;s++){ BX.push(e[s*2]); BY.push(e[s*2+1]); } }
const NB = BX.length;

// ---- lattice + coronas ----------------------------------------------------
const ax = cl(P.x,.2,.8)*width, ay = cl(P.y,.2,.8)*height;
const corner = Math.max(Math.hypot(ax,ay), Math.hypot(width-ax,ay), Math.hypot(ax,height-ay), Math.hypot(width-ax,height-ay));
const NMAX = 9;
const hexR = Math.max(u*.105*cl(P.scale,.55,2.0), corner/(1.732*NMAX + 1));
const NC = cl(Math.ceil(corner/(1.732*hexR) - .5) + 1, 1, NMAX);
const rot = K.t*.0132*sp + .10*Math.sin(K.t*.0713+1.4);

// ---- styles ---------------------------------------------------------------
const glow = (sty==='xray');
function grd(){
  if (sty==='riso')   return [44, 9, 93];
  if (sty==='verdi')  return [172, 34, 15];
  if (glow)           return [(H+192)%360, 56, 5];
  if (sty==='slate')  return [216, 13, 17];
  return [(H+10)%360, 30, 13];                 // inlay: dark shellac between cells
}
function cellCol(n, w, sh){
  const q = n/Math.max(1,NC);
  if (sty==='riso')  return [ (n%2) ? 352 : 205, 58 + 14*w, cl(96 - 26*(1-w) + 10*sh, 20, 100) ];
  if (sty==='verdi') return [ (168 + q*26 + w*22)%360, cl(44 - 18*w,6,90), cl(30 + 46*sh + 30*w, 6, 96) ];
  if (glow)          return [ (H + 130 + q*100 + w*60)%360, 42, cl(30 + 70*w + 40*sh, 4, 100) ];
  if (sty==='slate') return [ 214, cl(8 + 8*w,0,40), cl(24 + 48*sh + 26*w, 5, 92) ];
  return [ (H + 4 + q*20 + w*16)%360, cl(52 - 22*w, 8, 80), cl(28 + 50*sh + 30*w, 5, 96) ];
}

const gc = grd(); noStroke(); background(gc[0], gc[1], gc[2]);

// light direction orbits -> every cell's shading changes continuously
const lang = K.t*.077*sp + .6*Math.sin(K.t*.029+1.1);
const lgx = Math.cos(lang), lgy = Math.sin(lang);
const wavT = K.t*(.55 + .95*sp) + .8*Math.sin(K.t*.043);
const rw = cl(P.rings,0,1);

push(); translate(ax, ay); rotate(rot);
strokeJoin(ROUND); strokeWeight((u/900)*(.7 + 2.0*en));
const inner = cl(P.density,0,1) > .22;

for (let a=-NC;a<=NC;a++){
  for (let b=-NC;b<=NC;b++){
    const n = (Math.abs(a) + Math.abs(b) + Math.abs(a+b))*.5;    // axial hex distance
    if (n > NC) continue;
    const cx = (a*TXv[0] + b*TXv[1])*hexR, cy = (a*TYv[0] + b*TYv[1])*hexR;
    if (Math.abs(cx) > corner + hexR*1.8 || Math.abs(cy) > corner + hexR*1.8) continue;
    // the corona wave: rings of state change rippling out through the layers
    const w = rw * Math.pow(Math.max(0, Math.sin(n*.92 - wavT)), 2) * (.65 + .5*bass) * lift;
    const jit = fr(a*31.7 + b*17.3);
    // flat shade off the orbiting light
    const dl = Math.hypot(cx,cy) || 1;
    const sh = (.34 + .5*((cx/dl)*lgx + (cy/dl)*lgy)*.5 + .5*.5) * (.6 + .55*en) + .12*jit;
    const c = cellCol(n, w, sh);
    fill(c[0], c[1], c[2], glow ? cl(38 + 54*w, 14, 96) : 100);
    stroke(gc[0], cl(gc[1]*1.15,0,100), cl(gc[2]*(.45+.5*(1-en)),0,100), 88);
    beginShape();
    for (let s=0;s<NB;s++) vertex(cx + BX[s]*hexR, cy + BY[s]*hexR);
    endShape(CLOSE);
    if (inner) {                              // inlaid contour -> engraved relief
      noFill();
      stroke(c[0], cl(c[1]+16,0,100), cl(c[2]*.52,0,100), 30 + 46*cl(P.density,0,1));
      strokeWeight((u/900)*(.5 + .9*en));
      const k2 = .80 - .10*cl(P.density,0,1);
      beginShape();
      for (let s=0;s<NB;s++) vertex(cx + BX[s]*hexR*k2, cy + BY[s]*hexR*k2);
      endShape(CLOSE);
      stroke(c[0], c[1], cl(c[2]*1.35,0,100), 22 + 30*w);
      strokeWeight((u/900)*(.4 + .7*en));
      const k3 = k2*.56;
      beginShape();
      for (let s=0;s<NB;s++) vertex(cx + BX[s]*hexR*k3, cy + BY[s]*hexR*k3);
      endShape(CLOSE);
      strokeWeight((u/900)*(.7 + 2.0*en));
    }
  }
}
pop();

// ---- moving chiaroscuro ---------------------------------------------------
const lw2 = 180, lh2 = cl(Math.round(180*height/Math.max(1,width)), 60, 340);
if (!S.lg || S.lgk !== lw2+'x'+lh2) { S.lg = createGraphics(lw2, lh2); S.lg.colorMode(HSB,360,100,100,100); S.lgk = lw2+'x'+lh2; }
const L = S.lg;
L.push(); L.noStroke(); L.blendMode(BLEND);
L.background(0, 0, 100 - (18 + 30*en));
L.blendMode(ADD);
const plx = (.5 + .28*Math.sin(K.t*.067+.7))*lw2, ply = (.5 + .24*Math.cos(K.t*.053+2.4))*lh2;
for (let i=0;i<9;i++){
  const q=i/8, rr=Math.max(lw2,lh2)*(1.26-q*.98);
  L.fill(0,0,100, (6.5 + 7*en + 5*bass)*(.28+.72*q*q));
  L.ellipse(plx, ply, rr*2, rr*2);
}
L.blendMode(BLEND); L.pop();
blendMode(MULTIPLY); noStroke(); image(L, 0, 0, width, height); blendMode(BLEND);

// ---- cached grain ---------------------------------------------------------
const tk = sty+'|'+sd;
if (!S.tex || S.texk !== tk) {
  const tw=420, th=280, t=createGraphics(tw,th);
  t.colorMode(HSB,360,100,100,100); t.background(0,0,100); t.noStroke();
  for (let i=0;i<2200;i++){
    const rr=.4+fr(i*4.31)*1.8;
    t.fill(30, 8, 100-fr(i*6.77)*42, 50);
    t.ellipse(fr(i*2.53)*tw, fr(i*3.79+5.1)*th, rr, rr);
  }
  S.tex = t; S.texk = tk;
}
blendMode(MULTIPLY); noStroke(); image(S.tex, 0, 0, width, height); blendMode(BLEND);

if (P.alpha < 100) { noStroke(); fill(0,0,0, 100 - cl(P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0;
